BEGIN;
SELECT pg_advisory_xact_lock(8510402);
CREATE TABLE IF NOT EXISTS tenants(id uuid PRIMARY KEY,name text NOT NULL,enabled boolean NOT NULL DEFAULT true,settings jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS session(sid varchar PRIMARY KEY,sess json NOT NULL,expire timestamp(6) NOT NULL);
CREATE INDEX IF NOT EXISTS session_expire_idx ON session(expire);
CREATE TABLE IF NOT EXISTS runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),source text NOT NULL,status text NOT NULL DEFAULT 'queued',started_at timestamptz,finished_at timestamptz,window_start timestamptz,window_end timestamptz,records integer NOT NULL DEFAULT 0,error_code text,detail jsonb NOT NULL DEFAULT '{}',requested_by text,lease_until timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS running_source_idx ON runs(tenant_id,source) WHERE status IN ('queued','running');
CREATE TABLE IF NOT EXISTS coverage(tenant_id uuid NOT NULL REFERENCES tenants(id),source text NOT NULL,status text NOT NULL DEFAULT 'never',last_success timestamptz,last_attempt timestamptz,checkpoint timestamptz,records integer NOT NULL DEFAULT 0,detail jsonb NOT NULL DEFAULT '{}',PRIMARY KEY(tenant_id,source));
CREATE TABLE IF NOT EXISTS collection_cursors(tenant_id uuid NOT NULL REFERENCES tenants(id),source text NOT NULL,state jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,source));
CREATE TABLE IF NOT EXISTS evidence(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),source text NOT NULL,native_id text NOT NULL,payload jsonb NOT NULL,sha256 text NOT NULL,observed_at timestamptz NOT NULL DEFAULT now(),run_id uuid REFERENCES runs(id),UNIQUE(tenant_id,source,native_id,sha256));
CREATE TABLE IF NOT EXISTS resources(tenant_id uuid NOT NULL REFERENCES tenants(id),key text NOT NULL,source text NOT NULL,native_id text NOT NULL,name text NOT NULL,kind text NOT NULL,service text NOT NULL,parent_key text,created_at timestamptz,created_by text,first_seen timestamptz NOT NULL DEFAULT now(),last_seen timestamptz NOT NULL DEFAULT now(),active boolean NOT NULL DEFAULT true,properties jsonb NOT NULL DEFAULT '{}',evidence_id uuid REFERENCES evidence(id),run_id uuid REFERENCES runs(id),PRIMARY KEY(tenant_id,key));
CREATE INDEX IF NOT EXISTS resources_source_idx ON resources(tenant_id,source,service,active);
CREATE TABLE IF NOT EXISTS resource_versions(tenant_id uuid NOT NULL REFERENCES tenants(id),resource_key text NOT NULL,sha256 text NOT NULL,evidence_id uuid NOT NULL REFERENCES evidence(id),observed_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,resource_key,sha256));
CREATE TABLE IF NOT EXISTS edges(tenant_id uuid NOT NULL REFERENCES tenants(id),key text NOT NULL,source text NOT NULL,from_key text NOT NULL,to_key text NOT NULL,relation text NOT NULL,scope text,role text,active boolean NOT NULL DEFAULT true,properties jsonb NOT NULL DEFAULT '{}',evidence_id uuid REFERENCES evidence(id),run_id uuid REFERENCES runs(id),last_seen timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,key));
CREATE INDEX IF NOT EXISTS edges_path_idx ON edges(tenant_id,from_key,to_key,relation,active);
CREATE TABLE IF NOT EXISTS events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),source text NOT NULL,native_id text NOT NULL,occurred_at timestamptz,observed_at timestamptz NOT NULL DEFAULT now(),actor_key text,actor_name text,target_key text,target_name text,operation text NOT NULL,category text NOT NULL,outcome text,severity text NOT NULL DEFAULT 'info',correlation_id text,evidence_id uuid NOT NULL REFERENCES evidence(id),properties jsonb NOT NULL DEFAULT '{}',UNIQUE(tenant_id,source,native_id));
CREATE INDEX IF NOT EXISTS timeline_idx ON events(tenant_id,occurred_at DESC,id);
CREATE TABLE IF NOT EXISTS audit_ledger(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),at timestamptz NOT NULL DEFAULT now(),actor text NOT NULL,action text NOT NULL,target text NOT NULL,details jsonb NOT NULL DEFAULT '{}',previous_hash text NOT NULL,sha256 text NOT NULL);
CREATE INDEX IF NOT EXISTS ledger_tenant_idx ON audit_ledger(tenant_id,id);
CREATE TABLE IF NOT EXISTS bridge_nonces(tenant_id uuid NOT NULL REFERENCES tenants(id),nonce text NOT NULL,at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,nonce));
CREATE OR REPLACE FUNCTION atlas_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Append-only evidence / audit'; END $$;
DROP TRIGGER IF EXISTS immutable_evidence ON evidence;
CREATE TRIGGER immutable_evidence BEFORE UPDATE OR DELETE OR TRUNCATE ON evidence FOR EACH STATEMENT EXECUTE FUNCTION atlas_immutable();
DROP TRIGGER IF EXISTS immutable_ledger ON audit_ledger;
CREATE TRIGGER immutable_ledger BEFORE UPDATE OR DELETE OR TRUNCATE ON audit_ledger FOR EACH STATEMENT EXECUTE FUNCTION atlas_immutable();
COMMIT;
